contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 1000",
      "description": "The number of abbreviations n is between 1 and 1000 inclusive."
    },
    {
      "id": "P2",
      "expression": "all(abbreviation.startswith('IAO\'') for abbreviation in abbreviations)",
      "description": "Each abbreviation starts with 'IAO' followed by a single quote."
    },
    {
      "id": "P3",
      "expression": "all(1 <= len(abbreviation[4:]) <= 9 for abbreviation in abbreviations)",
      "description": "Each abbreviation has between 1 and 9 digits after 'IAO''."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "all(1989 <= year <= 9999 for year in years)",
      "description": "Each determined year is between 1989 and 9999 inclusive."
    },
    {
      "id": "Q2",
      "expression": "all(abbreviation == f'IAO\'{year % (10 ** len(abbreviation[4:]))}' for abbreviation, year in zip(abbreviations, years))",
      "description": "Each abbreviation matches the determined year's last digits."
    }
  ],
  "invariants": []
}
